module.exports = async (req, res) => {
    let body = req.json();

    var baseUri = req.get('x-dv-baseUri');
    if (!baseUri) {
        baseUri = req.var('baseUri');
    }
    const response = await fetch(baseUri + "/notification/notificationmessage", {
        method: 'POST',
        headers: {
            'Content-Type': 'application/hal+json',
            'Origin': baseUri,
            "Authorization": getAuthorizationHeader(req) 
            },
        body : JSON.stringify({ 
                'message': body.input.message,
                'messageHTML': body.input.message,
                'recipients': [body.input.recipient.substring(40)],
                'subject': body.input.subject,
            })
    });

    const status = response.status;
    if (status < 200 || status > 299) {
        throw new Error(`Unable to fetch HAL JSON from server. Received status ${status}`, response);
    }
    res.status(200);
}

function getAuthorizationHeader(req) {
    const cookies = parseCookies(req);
    var authorizationHeader = req.get('Authorization');
    if (cookies.AuthSessionId != null && cookies.AuthSessionId != "") {
        authorizationHeader = 'Bearer ' + cookies.AuthSessionId;
    }
    return authorizationHeader;
}

function parseCookies(request) {
    const list = {};
    const cookieHeader = request.get('cookie');
    if (!cookieHeader) return list;

    cookieHeader.split(`;`).forEach(function (cookie) {
        let [name, ...rest] = cookie.split(`=`);
        name = name?.trim();
        if (!name) return;
        const value = rest.join(`=`).trim();
        if (!value) return;
        list[name] = decodeURIComponent(value);
    });

    return list;
}
